const source = $json._source;
const alertaId = $json._id;
const eventdata = source?.data?.win?.eventdata || {};
const hashesStr = eventdata.hashes || "";

const match = hashesStr.match(/SHA256=([A-Fa-f0-9]{64})/);
const sha256 = match ? match[1] : null;

return {
  json: {
    alerta_id: alertaId,
    regla_id: source.rule?.id ?? null,
    nivel: source.rule?.level ?? null,
    descripcion: source.rule?.description ?? "N/A",
    mitre_id: source.rule?.mitre?.id?.[0] ?? "N/A",
    mitre_tactic: (source.rule?.mitre?.tactic || []).join(", ") || "N/A",
    imagen: eventdata.image ?? "N/A",
    comando: eventdata.commandLine ?? "N/A",
    sha256: sha256,
    agente_nombre: source.agent?.name ?? "N/A",
    agente_ip: source.agent?.ip ?? "N/A",
    usuario_origen: eventdata.user ?? "N/A",
    timestamp: source["@timestamp"] ?? source.timestamp ?? "N/A",
    firedtimes: source.rule?.firedtimes ?? "N/A"
  }
};

