const sqlite3 = require('sqlite3').verbose();
const path = '/home/node/.n8n/db/soc_alerts.db';

const vtData = $json.data;
const alertaOriginal = $('Code in JavaScript').item.json;

let vtEstado, vtMaliciosos, vtSospechosos, vtTotalMotores;

if (!vtData) {
  vtEstado = 'sin_registro';
  vtMaliciosos = null;
  vtSospechosos = null;
  vtTotalMotores = null;
} else {
  const stats = vtData.attributes?.last_analysis_stats || {};
  vtEstado = 'ok';
  vtMaliciosos = stats.malicious ?? 0;
  vtSospechosos = stats.suspicious ?? 0;
  vtTotalMotores = Object.values(stats).reduce((a, b) => a + b, 0);
}

return new Promise((resolve, reject) => {
  const db = new sqlite3.Database(path, sqlite3.OPEN_READWRITE, (err) => {
    if (err) {
      reject(new Error('Error abriendo DB: ' + err.message));
      return;
    }
    const sql = `INSERT OR REPLACE INTO alertas
      (alerta_id, regla_id, nivel, descripcion, mitre_id, imagen, sha256, vt_maliciosos, vt_sospechosos, vt_total_motores, vt_estado)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;

    db.run(sql, [
      alertaOriginal.alerta_id,
      alertaOriginal.regla_id,
      alertaOriginal.nivel,
      alertaOriginal.descripcion,
      alertaOriginal.mitre_id,
      alertaOriginal.imagen,
      alertaOriginal.sha256,
      vtMaliciosos,
      vtSospechosos,
      vtTotalMotores,
      vtEstado
    ], (err) => {
      db.close();
      if (err) {
        reject(new Error('Error insertando: ' + err.message));
        return;
      }
      resolve($json);
    });
  });
});

function escMd2(text) {
  return String(text).replace(/[_*\[\]()~`>#+\-=|{}.!\\]/g, '\\$&');
}
function escMd2Code(text) {
  return String(text).replace(/[`\\]/g, '\\$&');
}
function truncar(text, max) {
  const s = String(text);
  return s.length > max ? s.slice(0, max) + "..." : s;
}

const vtData = $json.data;
const a = $('Code in JavaScript').item.json;

let resumenVT;
if (!vtData) {
  resumenVT = "Sin registro en VirusTotal (archivo no visto antes)";
} else {
  const stats = vtData.attributes?.last_analysis_stats || {};
  const maliciosos = stats.malicious ?? 0;
  const sospechosos = stats.suspicious ?? 0;
  const total = Object.values(stats).reduce((x, y) => x + y, 0);
  const nombres = (vtData.attributes?.names || []).slice(0, 3).join(", ");
  resumenVT = `${maliciosos} maliciosos / ${sospechosos} sospechosos / ${total} motores` +
              (nombres ? ` | Nombres vistos: ${nombres}` : "");
}

const nivelNum = Number(a.nivel) || 0;
let severityEmoji;
if (nivelNum >= 15) severityEmoji = "🚨";
else if (nivelNum >= 12) severityEmoji = "🔴";
else if (nivelNum >= 7) severityEmoji = "🟡";
else severityEmoji = "🟢";

const comandoCorto = truncar(a.comando, 400);

const texto =
`🚨 *ALERTA DE SEGURIDAD WAZUH* 🚨

${severityEmoji} *Nivel de Severidad:* ${escMd2(a.nivel)}

📌 *DATOS DEL OBJETIVO*
• Agente: ${escMd2(a.agente_nombre)}
• IP Origen: ${escMd2(a.agente_ip)}
• Timestamp: ${escMd2(a.timestamp)}

📋 *DETALLES DE LA REGLA*
• ID Regla: ${escMd2(a.regla_id)}
• Descripción: ${escMd2(a.descripcion)}
• Frecuencia: Disparada ${escMd2(a.firedtimes)} veces

👤 *CONTEXTO DE USUARIO*
• Usuario Origen: ${escMd2(a.usuario_origen)}
• Comando Ejecutado: \`${escMd2Code(comandoCorto)}\`

🎯 *INTELIGENCIA MITRE ATT&CK*
• Táctica: ${escMd2(a.mitre_tactic)}
• Técnica: ${escMd2(a.mitre_id)}

🦠 *VIRUSTOTAL*
${escMd2(resumenVT)}

📄 *EVIDENCIA*
• Imagen: \`${escMd2Code(a.imagen)}\`
• SHA256: \`${escMd2Code(a.sha256)}\``;

return { json: { text: texto } };
